struct app_state { int selected; const char *items[MAX_ITEMS]; size_t n; };  /* owned by app.c */

/* stateless child: reads the snapshot, writes nothing */
static void render_list(FILE *out, const struct app_state *s)
{
    for (size_t i = 0; i < s->n; i++)
        fprintf(out, "<li%s>%s</li>\n", i == s->selected ? " class=\"on\"" : "", s->items[i]);
}

/* event path: the owner mutates, the caller re-renders */
static void on_select(struct app_state *s, int idx) { s->selected = idx; }
